import React from "react";

const strategi = [
  'Individu: MFA, password manager, literasi digital.',
  'Perusahaan: Filter email, DMARC/SPF, simulasi phishing.',
];

export default function Slide9StrategiPerlindungan({ onNext, onPrev }) {
  return (
    <div className="slide-content bg-gradient-to-r from-[#e0e7ef] to-[#b6c6e3] rounded-2xl p-8 md:p-12 shadow-xl">
      <h2 className="slide-title mb-6 text-blue-700">Strategi Perlindungan</h2>
      <ul className="text-lg text-gray-800 mb-6 space-y-3">
        {strategi.map((s, i) => (
          <li key={i} className="flex items-center gap-3"><span className="text-blue-600">🔒</span>{s}</li>
        ))}
      </ul>
      <div className="text-gray-700 mb-8">Teknologi penting, tapi kesadaran jauh lebih efektif!</div>
      <div className="flex gap-4 justify-center">
        <button onClick={onPrev} className="bg-gray-200 text-blue-700 px-4 py-2 rounded-lg font-bold hover:bg-gray-300 transition">Back</button>
        <button onClick={onNext} className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold text-lg shadow hover:bg-blue-700 transition">Next</button>
      </div>
    </div>
  );
}
